import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).trim();
        int best = 0;
        for (int i = 0; i + 1 < s.length(); i++) best = Math.max(best, (s.charAt(i) - '0') * 10 + (s.charAt(i + 1) - '0'));
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	s := strings.TrimSpace(string(data))
	best := 0
	for i := 0; i+1 < len(s); i++ {
		best = max(best, int(s[i]-'0')*10+int(s[i+1]-'0'))
	}
	fmt.Println(best)
}
